CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TABLE projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_number text NOT NULL UNIQUE, upstream_uuid text UNIQUE, upstream_puuid text, title text, description text, status text, municipality text, competent_authority text, publication_type text, latitude text, longitude text, publication_start_at timestamptz, publication_end_at timestamptz, appeal_end_at timestamptz, is_currently_public boolean NOT NULL DEFAULT true, first_seen_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), last_crawled_at timestamptz, next_crawl_at timestamptz, crawl_status text NOT NULL DEFAULT 'pending', crawl_attempts integer NOT NULL DEFAULT 0, last_crawl_error text, source_metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE project_phases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, upstream_uuid text NOT NULL, phase_type text, source_metadata jsonb NOT NULL DEFAULT '{}'::jsonb, first_seen_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id, upstream_uuid));
CREATE TABLE events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, phase_id uuid REFERENCES project_phases(id) ON DELETE SET NULL, upstream_uuid text NOT NULL UNIQUE, category text, event_code text, first_seen_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), source_metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, event_id uuid REFERENCES events(id) ON DELETE SET NULL, content_id text, upstream_uuid text NOT NULL UNIQUE, source_type text NOT NULL DEFAULT 'procedure_event', category text, filename text NOT NULL, description text, mime_type text, size_bytes integer, security_category text, downloadable boolean NOT NULL, download_status text NOT NULL, storage_key text, sha256 text, first_seen_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), downloaded_at timestamptz, attempt_count integer NOT NULL DEFAULT 0, next_attempt_at timestamptz, last_error text, source_metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE crawl_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), type text NOT NULL, project_id uuid REFERENCES projects(id) ON DELETE CASCADE, document_id uuid REFERENCES documents(id) ON DELETE CASCADE, payload jsonb, status text NOT NULL DEFAULT 'pending', priority integer NOT NULL DEFAULT 0, attempts integer NOT NULL DEFAULT 0, max_attempts integer NOT NULL DEFAULT 5, next_attempt_at timestamptz NOT NULL DEFAULT now(), locked_at timestamptz, locked_by text, lease_expires_at timestamptz, last_error text, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE crawl_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), worker_id text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, status text NOT NULL DEFAULT 'running', tasks_claimed integer NOT NULL DEFAULT 0, tasks_completed integer NOT NULL DEFAULT 0, tasks_failed integer NOT NULL DEFAULT 0, projects_discovered integer NOT NULL DEFAULT 0, projects_updated integer NOT NULL DEFAULT 0, documents_discovered integer NOT NULL DEFAULT 0, documents_downloaded integer NOT NULL DEFAULT 0, documents_failed integer NOT NULL DEFAULT 0, requests_sent integer NOT NULL DEFAULT 0, last_error text);
CREATE TABLE crawler_state (id integer PRIMARY KEY DEFAULT 1, paused boolean NOT NULL DEFAULT false, pause_reason text, last_heartbeat_at timestamptz, last_successful_upstream_request_at timestamptz, last_rate_limit_at timestamptz, last_discovery_at timestamptz, current_discovery_cursor jsonb);
CREATE TABLE discovery_partitions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), strategy text NOT NULL, partition_key text NOT NULL, cursor jsonb, status text NOT NULL DEFAULT 'pending', next_attempt_at timestamptz, last_error text, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(strategy, partition_key));
CREATE INDEX projects_public_idx ON projects(is_currently_public); CREATE INDEX projects_next_crawl_idx ON projects(next_crawl_at); CREATE INDEX events_project_idx ON events(project_id); CREATE INDEX documents_project_idx ON documents(project_id); CREATE INDEX documents_status_idx ON documents(download_status); CREATE INDEX documents_next_attempt_idx ON documents(next_attempt_at); CREATE INDEX crawl_tasks_claim_idx ON crawl_tasks(status, next_attempt_at); CREATE INDEX crawl_tasks_project_idx ON crawl_tasks(project_id); CREATE INDEX crawl_tasks_document_idx ON crawl_tasks(document_id); CREATE UNIQUE INDEX crawl_tasks_active_project_unique ON crawl_tasks(type, project_id) WHERE status IN ('pending','running') AND project_id IS NOT NULL; CREATE UNIQUE INDEX crawl_tasks_active_document_unique ON crawl_tasks(type, document_id) WHERE status IN ('pending','running') AND document_id IS NOT NULL;
